mapper.select:
SELECT 
	ISNULL(MIN(DD.출고일자),#{searchDtFrom}) AS DD_MAX_DATE



	 AND DD.출고일자 >= #{listStartDt}

mapper.sql:


WHERE 1=1
	AND DD.거래처코드 = #{bcncCode}
	AND DH.거래명세발행여부 = 'Y'
	AND DH.출고거래처 IN (SELECT CM2.거래처코드
						FROM 거래처MASTER CM2
						WHERE CM2.등록사업장 = #{registBplc}

				 AND RTRIM(CM2.상호) LIKE UPPER('%'+#{searchEntrpsNm}+'%') 
			  ) 


 AND DD.출고일자 >= #{searchDtFrom} 


 AND DD.출고일자 <= #{searchDtTo} 


 AND RTRIM(IC.품목명) LIKE UPPER('%'+#{searchItemNm}+'%')
